-- 0012: player-to-player marketplace listings (assets are held in escrow inside the listing). Mirrors later-schema.js (n: 12).
CREATE TABLE IF NOT EXISTS market_listings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, seller_id BIGINT NOT NULL, kind TEXT NOT NULL, item_ref TEXT NOT NULL, snapshot TEXT NOT NULL, ask BIGINT NOT NULL, base_value BIGINT NOT NULL, listing_fee BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'open', created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, buyer_id BIGINT, sold_at BIGINT, sale_fee BIGINT NOT NULL DEFAULT 0, returned_at BIGINT);
CREATE INDEX IF NOT EXISTS ix_market_open ON market_listings(status, kind, ask);
CREATE INDEX IF NOT EXISTS ix_market_seller ON market_listings(seller_id, status);
CREATE INDEX IF NOT EXISTS ix_market_buyer ON market_listings(buyer_id);
